def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper: run a read-only query safely; return empty list on any DB error
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    expected_title = "How to fix TypeError: unsupported operand type(s) for +: int and str in Python?"
    required_tags = {"python", "typeerror", "python-3.x"}
    current_user_id = 1

    # 1) Collect initial question IDs with the exact title
    initial_q_rows = safe_query(
        initial_db_path,
        "SELECT id FROM questions WHERE title = ?",
        (expected_title,)
    )
    initial_ids = {row[0] for row in initial_q_rows if isinstance(row, tuple) and len(row) > 0 and isinstance(row[0], int)}

    # 2) Get final questions with the exact title
    final_q_rows = safe_query(
        final_db_path,
        "SELECT id, owner_user_id, body FROM questions WHERE title = ?",
        (expected_title,)
    )

    if not final_q_rows:
        return {"result": "others"}

    # Precompile regex patterns
    py311_re = re.compile(r"python\s*3\.11", re.IGNORECASE)
    code_re = re.compile(r"(?i)total\s*=\s*5\s*\+\s*'3'")

    # Helper to get tag names for a question id in final DB
    def get_tag_names_for_question(qid: int) -> set:
        rows = safe_query(
            final_db_path,
            "SELECT t.name FROM question_tags qt JOIN tags t ON t.id = qt.tag_id WHERE qt.question_id = ?",
            (qid,)
        )
        names = set()
        for r in rows:
            if isinstance(r, tuple) and len(r) > 0 and isinstance(r[0], str):
                names.add(r[0].strip().lower())
        return names

    # 3) Validate existence of a new qualifying question
    for row in final_q_rows:
        if not (isinstance(row, tuple) and len(row) >= 3):
            continue
        qid, owner_user_id, body = row[0], row[1], row[2]
        # Must be a new question (id not present in initial set)
        if not isinstance(qid, int) or qid in initial_ids:
            continue
        # Must be owned by current_user
        if owner_user_id != current_user_id:
            continue
        # Body checks
        if not isinstance(body, str) or body.strip() == "":
            continue
        if py311_re.search(body) is None:
            continue
        if code_re.search(body) is None:
            continue
        # Tag checks: required tags must be included
        tag_names = get_tag_names_for_question(qid)
        if not tag_names:
            continue
        if not required_tags.issubset(tag_names):
            continue
        # All checks passed for this new question
        return {"result": "complete"}

    return {"result": "others"}

